import json
res = json.load(open('pro_eval/eval_results.json'))
tests = json.load(open('evaluation_scripts/task_test.json'))
def L(v):
    while isinstance(v, str):
        try: v = json.loads(v)
        except Exception: return [v]
    out = []
    for x in v:
        out += L(x) if isinstance(x, str) and x.startswith('[') else [x]
    return out
for iid, ok in res.items():
    if ok: continue
    t = tests[iid]
    f2p, p2p = L(t['fail_to_pass']), L(t['pass_to_pass'])
    out = json.load(open(f'pro_eval/{iid}/madsLoop_output.json'))
    status = {x['name']: x['status'] for x in out.get('tests', [])}
    bf = [n for n in f2p if status.get(n) != 'PASSED']
    bp = [n for n in p2p if status.get(n) != 'PASSED']
    print(f"\n### {iid[:75]}")
    print(f"  fail_to_pass: {len(f2p)-len(bf)}/{len(f2p)} pass | pass_to_pass: {len(p2p)-len(bp)}/{len(p2p)} pass | tests reported: {len(status)}")
