"""Tool schemas (what the model sees) and executors (what the harness runs)."""
import os
import subprocess

MAX_OUTPUT_CHARS = 12000
BASH_TIMEOUT_S = 300

TOOL_SCHEMAS = [
    {
        "type": "function",
