import os
import subprocess

MAX_OUTPUT_CHARS = 12000
BASH_TIMEOUT_S = 300

TOOL_SCHEMAS = [
    {
        "type": "function",
        "function": {
            "name": "bash",
            "description": "Run a shell command in the repository root and return stdout+stderr. "
                           f"Times out after {BASH_TIMEOUT_S}s. Use for grep/find/ls, running tests and scripts.",
            "parameters": {
